import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Filter out near-duplicates based on correlation
    ids = list(feats.ids)
    types = list(feats.types)
    x = feats.x
    y = feats.y

    # Build correlation matrix
    corr_matrix = np.corrcoef(x.T)
    corr_pairs = []
    for i in range(len(ids)):
        for j in range(i+1, len(ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                corr_pairs.append((ids[i], ids[j]))

    # Group correlated features
    groups = []
    used = set()
    for a, b in corr_pairs:
        if a in used or b in used:
            continue
        group = {a, b}
        used.add(a)
        used.add(b)
        # Add all features correlated with members of this group
        for c, d in corr_pairs:
            if c in group or d in group:
                group.add(c)
                group.add(d)
                used.add(c)
                used.add(d)
        groups.append(group)

    # For each group, find the most associated feature with outcome
    drivers = []
    for group in groups:
        if len(group) == 1:
            drivers.extend(list(group))
        else:
            # Find feature with highest absolute effect size
            best_feature = None
            max_effect = 0
            for fid in group:
                col_idx = feats.column(fid)
                effect = np.mean(x[y==1, col_idx]) - np.mean(x[y==0, col_idx])
                if abs(effect) > max_effect:
                    max_effect = abs(effect)
                    best_feature = fid
            if best_feature:
                drivers.append(best_feature)

    # Remove duplicates and limit to MAX_DRIVERS
    seen = set()
    unique_drivers = []
    for d in drivers:
        if d not in seen:
            unique_drivers.append(d)
            seen.add(d)
    drivers = unique_drivers[:MAX_DRIVERS]

    # If no drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select features for regression
    columns = list(set(drivers))
    products = []
    loadings = {}

    # Add main effects
    for fid in drivers:
        col_idx = feats.column(fid)
        effect = np.mean(x[y==1, col_idx]) - np.mean(x[y==0, col_idx])
        loadings[fid] = effect

    # Add interaction terms between top drivers
    if len(drivers) >= 2:
        for i in range(min(2, len(drivers))):
            for j in range(i+1, min(3, len(drivers))):
                a, b = drivers[i], drivers[j]
                products.append((a, b))

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

